import { test, expect } from '@playwright/test';

// Recording findings (from the session data — surfaced, never assertions):
//   - Session capture masks and drops sensitive fields (e.g. card numbers, passwords), so the recording may not carry every value this submit needs — if the replayed submit does not reach the expected page, a masked field the recording never captured needs its value added above it.
//   - This flow performs writes (form submissions). Run generated tests against a safe environment — point TARGET_APP_URL at staging/seeded data, never production.
//   - Final-URL pattern confirmed across 5 sampled sessions.
//   - Final page text confirmed across 5 sampled sessions.
//   - Aggregated across 5 sampled sessions of this journey (5 candidates found; 0 fetch-failures/non-matches).

test.use({ viewport: { width: 1280, height: 800 } });

test('Inv 1003', async ({ page, baseURL }) => {
  const consoleErrors: string[] = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });

  await page.goto('/');
  await page.getByRole('link', { name: 'Invoices' }).click();
  await page.getByTestId('view-invoice-inv-1003').click();
  await page.getByTestId('pay-invoice-link').click();
  // Finishing steps: TODO fills resolved with synthetic test values,
  // and the two masked required fields the recording could not capture (card
  // number, CVC — session capture masks them by design) supplied per the
  // "add its synthetic fill" guidance that shipped with this draft.
  await page.locator('#card-name').fill('Miguel Torres');
  await page.locator('#card-expiry').fill('12/28');
  await page.getByLabel('Billing email').fill('miguel.torres@example.com');
  await page.locator('#card-number').fill('4242 4242 4242 4242'); // masked required field — recording never carried it
  await page.locator('#card-cvc').fill('123'); // masked required field — recording never carried it
  await page.getByTestId('pay-invoice').click();
  await page.getByTestId('confirm-payment').click();
  await page.getByRole('button', { name: 'Back to invoice' }).click();

  await expect(page).toHaveURL(baseURL === undefined ? /^(?:[^/]+:\/\/[^/]+)?\/invoices\/[^\/]+$/ : new RegExp('^' + new URL(baseURL).origin.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\/invoices\\/[^\\/]+$')); // baseURL undefined: retain the sidecar's stored pattern unchanged.
  await expect(page).toHaveTitle('Acme Ops Console');
  expect(consoleErrors).toEqual([]);
});
